//! Writing the description out as Rust source.
//!
//! Everything emitted is a `&'static` literal, so the crate stays `no_std`
//! with no allocator and a consumer pays nothing to read it.

use std::fmt::Write;

use crate::source::Source;
use crate::walk::{Command, Description, Kind, Opt};

/// The whole of `description.rs`.
pub fn emit(description: &Description) -> String {
    let mut out = String::new();

    out.push_str(
        "// Generated by build/, from rust/cli/src/args/.  Do not edit.\n\n\
         /// The options every One ROM CLI command accepts.\n\
         ///\n\
         /// They are not repeated on a [`Command`], so a pane shows them once.\n\
         pub static GLOBALS: &[Opt] = &[\n",
    );
    for opt in &description.globals {
        opt_out(&mut out, opt, 1);
    }
    out.push_str("];\n\n");

    out.push_str(
        "/// Every One ROM CLI command, in the order the CLI declares them.\n\
         pub static COMMANDS: &[Command] = &[\n",
    );
    for command in &description.commands {
        command_out(&mut out, command);
    }
    out.push_str("];\n");

    out
}

fn command_out(out: &mut String, command: &Command) {
    let indent = pad(1);
    let _ = writeln!(out, "{indent}Command {{");
    let _ = writeln!(out, "{indent}    path: {},", strings(&command.path));
    let _ = writeln!(out, "{indent}    about: {},", string(&command.about));
    let _ = writeln!(
        out,
        "{indent}    long_about: {},",
        maybe(command.long_about.as_deref())
    );

    if command.opts.is_empty() {
        let _ = writeln!(out, "{indent}    opts: &[],");
    } else {
        let _ = writeln!(out, "{indent}    opts: &[");
        for opt in &command.opts {
            opt_out(out, opt, 3);
        }
        let _ = writeln!(out, "{indent}    ],");
    }

    if command.groups.is_empty() {
        let _ = writeln!(out, "{indent}    groups: &[],");
    } else {
        let _ = writeln!(out, "{indent}    groups: &[");
        for group in &command.groups {
            let inner = pad(3);
            let field = pad(4);
            let _ = writeln!(out, "{inner}Group {{");
            let _ = writeln!(out, "{field}name: {},", string(&group.name));
            let _ = writeln!(out, "{field}opts: {},", strings(&group.opts));
            let _ = writeln!(out, "{field}required: {},", group.required);
            let _ = writeln!(out, "{field}multiple: {},", group.multiple);
            let _ = writeln!(out, "{inner}}},");
        }
        let _ = writeln!(out, "{indent}    ],");
    }

    let _ = writeln!(out, "{indent}}},");
}

fn opt_out(out: &mut String, opt: &Opt, depth: usize) {
    let indent = pad(depth);
    let inner = pad(depth + 1);
    let _ = writeln!(out, "{indent}Opt {{");
    let _ = writeln!(out, "{inner}long: {},", string(&opt.long));
    let _ = writeln!(out, "{inner}aliases: {},", strings(&opt.aliases));
    let _ = writeln!(out, "{inner}help: {},", string(&opt.help));
    let _ = writeln!(
        out,
        "{inner}value_name: {},",
        maybe(opt.value_name.as_deref())
    );
    let _ = writeln!(out, "{inner}kind: {},", kind(&opt.kind));
    let _ = writeln!(out, "{inner}optional: {},", opt.optional);
    let _ = writeln!(out, "{inner}multiple: {},", opt.multiple);
    let _ = writeln!(out, "{inner}default: {},", maybe(opt.default.as_deref()));
    let _ = writeln!(out, "{inner}conflicts: {},", strings(&opt.conflicts));
    let _ = writeln!(out, "{inner}requires: {},", strings(&opt.requires));
    let _ = writeln!(out, "{inner}source: {},", source(opt.source));
    let _ = writeln!(out, "{indent}}},");
}

fn kind(kind: &Kind) -> String {
    match kind {
        Kind::Flag => "Kind::Flag".to_string(),
        Kind::Text => "Kind::Text".to_string(),
        Kind::Number => "Kind::Number".to_string(),
        Kind::Choice(values) => format!("Kind::Choice({})", strings(values)),
        Kind::Domain(name) => format!("Kind::Domain({})", string(name)),
    }
}

fn source(source: Option<Source>) -> String {
    match source {
        Some(source) => format!("Some(Source::{})", source.variant()),
        None => "None".to_string(),
    }
}

fn maybe(text: Option<&str>) -> String {
    match text {
        Some(text) => format!("Some({})", string(text)),
        None => "None".to_string(),
    }
}

fn strings(values: &[String]) -> String {
    let values: Vec<String> = values.iter().map(|value| string(value)).collect();
    format!("&[{}]", values.join(", "))
}

/// One string literal, escaped for the four characters that would break it.
///
/// The rest is left as it stands: the file is UTF-8 and the CLI's help is full
/// of em dashes and ellipses that escaping would make unreadable in a diff.
fn string(text: &str) -> String {
    let mut out = String::with_capacity(text.len() + 2);
    out.push('"');
    for character in text.chars() {
        match character {
            '"' => out.push_str("\\\""),
            '\\' => out.push_str("\\\\"),
            '\n' => out.push_str("\\n"),
            '\r' => out.push_str("\\r"),
            _ => out.push(character),
        }
    }
    out.push('"');
    out
}

fn pad(depth: usize) -> String {
    " ".repeat(depth * 4)
}
